CREATE PROCEDURE find_parts (
	seed INT
)
BEGIN
	DROP TABLE IF EXISTS _result;
	CREATE TEMPORARY TABLE _result (
		node INT PRIMARY KEY
	);
	INSERT INTO _result
	VALUES (seed);
	DROP TABLE IF EXISTS _tmp;
	CREATE TEMPORARY TABLE _tmp LIKE _result;
	REPEAT 
		TRUNCATE TABLE _tmp;
		INSERT INTO _tmp
		SELECT child AS node
		FROM _result
			JOIN nodes ON node = parent;
		INSERT IGNORE INTO _result
		SELECT node
		FROM _tmp;
	UNTIL ROW_COUNT() = 0
	END REPEAT;
	DROP TABLE _tmp;
	SELECT *
	FROM _result;
END;

