CREATE OR REPLACE PROCEDURE transfer (
	from_acct NUMBER, 
	to_acct NUMBER, 
	amount NUMBER
)
IS
BEGIN
	UPDATE accounts
	SET balance = balance - amount
	WHERE account_id = from_acct;
	UPDATE accounts
	SET balance = balance + amount
	WHERE account_id = to_acct;
	COMMIT WRITE NOWAIT IMMEDIATE;
END;

