CREATE OR REPLACE TRIGGER XON_EPM.EPM_TG_FIRSTCHECK
	AFTER INSERT OR UPDATE
	ON XON_EPM.EPM_TBL_FIRST_CERTIFICATION_AP
	FOR EACH ROW
DECLARE
	var_nContractID number;
	var_dFirstCheckTime date;
	var_nRecordCount number;
	var_sState varchar2(16);
BEGIN
	var_sState := :NEW.State;
	var_dFirstCheckTime := :NEW.Commiteddate;
	IF var_sState = 'approved' THEN
		-- 鏌ヨuE1D7鍚堝悓 ID
		SELECT etfca_.contractid
		INTO var_nContractID
		FROM XON_EPM.EPM_TBL_FIRST_CERTIFICATION etfc_, XON_EPM.EPM_TBL_FIRST_CHECK_APPLICATIO etfca_
		WHERE etfca_.oid = etfc_.applicationid
			AND etfc_.oid = :NEW.CERTIFICATIONID;
		IF var_nContractID > 0 THEN
			-- 鏌ヨuE1D7 EPM_TB_CONTRACT_EX 鏄uE21A惁鏈夎uE187褰�
			SELECT COUNT(*)
			INTO var_nRecordCount
			FROM XON_EPM.EPM_TB_CONTRACT_EX etce_
			WHERE etce_.ncontractid = var_nContractID;
			IF var_nRecordCount <= 0 THEN
				UPDATE XON_EPM.EPM_TBL_CONTRACT
				SET oid = oid
				WHERE XON_EPM.EPM_TBL_CONTRACT.OID = var_nContractID;
			END IF;
			UPDATE XON_EPM.EPM_TB_CONTRACT_EX
			SET dFirstCheckTime = var_dFirstCheckTime
			WHERE XON_EPM.EPM_TB_CONTRACT_EX.NCONTRACTID = var_nContractID;
		END IF;
	END IF;
END;

