CREATE TYPE BODY rational
  IS
   MAP MEMBER FUNCTION rat_to_real RETURN REAL IS
      BEGIN
         RETURN numerator/denominator;
      END;

   MEMBER PROCEDURE normalize IS
      gcd NUMBER := integer_operations.greatest_common_divisor
                     (numerator, denominator);
      BEGIN
         numerator := numerator/gcd;
         denominator := denominator/gcd;
      END;

   MEMBER FUNCTION plus(x rational) RETURN rational IS
      r rational := rational_operations.make_rational
                      (numerator*x.denominator +
                       x.numerator*denominator,
                       denominator*x.denominator);
      BEGIN
         RETURN r;
      END;

   END;

CREATE TYPE BODY rational IS
	MAP MEMBER FUNCTION rat_to_real () RETURN REAL
	IS
	BEGIN
		RETURN numerator / denominator;
	END;
	MEMBER PROCEDURE normalize
	IS
	gcd NUMBER := integer_operations.greatest_common_divisor(numerator, denominator);
	BEGIN
		numerator := numerator / gcd;
		denominator := denominator / gcd;
	END;
	MEMBER FUNCTION plus (x rational) RETURN rational
	IS
	r rational := rational_operations.make_rational(numerator * x.denominator + x.numerator * denominator, denominator * x.denominator);
	BEGIN
		RETURN r;
	END;
END;

