CREATE OR REPLACE type body connstrBycomma is
      static function ODCIAggregateInitialize(sctx IN OUT connstrBycomma)	
      return number is
      begin
        sctx := connstrBycomma('',',');
        return ODCIConst.Success;
      end;
      member function ODCIAggregateIterate(self IN OUT connstrBycomma, value IN VARCHAR2) return number is
      begin
        if self.currentstr is null then
          self.currentstr := value;
        else
          self.currentstr := self.currentstr ||currentseprator || value;
        end if;
        return ODCIConst.Success;
      end;
      member function ODCIAggregateTerminate(self IN connstrBycomma, returnValue OUT VARCHAR2, flags IN number) return number is
      begin
        returnValue := self.currentstr;
        return ODCIConst.Success;
      end;
      member function ODCIAggregateMerge(self IN OUT connstrBycomma, ctx2 IN connstrBycomma) return number is
      begin
        if ctx2.currentstr is null then
          self.currentstr := self.currentstr;
        elsif self.currentstr is null then
          self.currentstr := ctx2.currentstr;
        else
          self.currentstr := self.currentstr || currentseprator || ctx2.currentstr;
        end if;
        return ODCIConst.Success;
      end;
      end;

CREATE OR REPLACE TYPE BODY connstrBycomma IS
