		RETURN ODCIConst.Success;
	END;
	MEMBER FUNCTION ODCIAggregateIterate (self IN OUT connstrBycomma, value IN VARCHAR2) RETURN number
	IS
	BEGIN
		IF self.currentstr IS NULL THEN
			self.currentstr := value;
		ELSE
			self.currentstr := self.currentstr || currentseprator || value;
		END IF;
		RETURN ODCIConst.Success;
	END;
	MEMBER FUNCTION ODCIAggregateTerminate (self IN connstrBycomma, returnValue OUT VARCHAR2, flags IN number) RETURN number
	IS
